from solution import rearrange_bigger


def test_issue_example_12():
    """Create the next bigger number by rearranging the digits: 12 becomes 21."""
    assert rearrange_bigger(12) == 21  # 2*10+1 = 21


def test_issue_next_after_123():
    """Create the next bigger number by rearranging the digits: 123 becomes 132."""
    assert rearrange_bigger(123) == 132  # 1*100+3*10+2 = 132


def test_issue_pivot_jumps_to_front():
    """Create the next bigger number by rearranging the digits: 132 becomes 213."""
    assert rearrange_bigger(132) == 213  # 2*100+1*10+3 = 213


def test_issue_duplicate_digits():
    """Create the next bigger number by rearranging the digits: 121 becomes 211."""
    assert rearrange_bigger(121) == 211  # 2*100+1*10+1 = 211


def test_issue_with_zero_in_middle():
    """Create the next bigger number by rearranging the digits: 2017 becomes 2071."""
    assert rearrange_bigger(2017) == 2071  # 2*1000+0*100+7*10+1 = 2071


def test_issue_zeros_need_suffix_sort():
    """Create the next bigger number by rearranging the digits: 1200 becomes 2001."""
    assert rearrange_bigger(1200) == 2001  # 2*1000+0*100+0*10+1 = 2001


def test_issue_swap_last_two():
    """Create the next bigger number by rearranging the digits: 513 becomes 531."""
    assert rearrange_bigger(513) == 531  # 5*100+3*10+1 = 531


def test_issue_four_digits_ascending():
    """Create the next bigger number by rearranging the digits: 1234 becomes 1243."""
    assert rearrange_bigger(1234) == 1243  # 1*1000+2*100+4*10+3 = 1243


def test_issue_suffix_reorders():
    """Create the next bigger number by rearranging the digits: 534976 becomes 536479."""
    assert rearrange_bigger(534976) == 536479  # 5*100000+3*10000+6*1000+4*100+7*10+9 = 536479


def test_issue_repeated_digit():
    """Create the next bigger number by rearranging the digits: 11112 becomes 11121."""
    assert rearrange_bigger(11112) == 11121  # 1*10000+1*1000+1*100+2*10+1 = 11121


def test_contract_same_digits():
    """By rearranging the digits keeps the same digit multiset."""
    assert sorted(str(rearrange_bigger(2017))) == ["0", "1", "2", "7"]  # 2*1000+0*100+7*10+1 = 2071


def test_contract_result_is_bigger():
    """Next bigger number is greater than the input."""
    assert rearrange_bigger(513) > 513  # 5*100+3*10+1 = 531 > 513
